"use strict";(self.webpackChunksketch_blog=self.webpackChunksketch_blog||[]).push([[4448],{4439(a,e,t){t.r(e),t.d(e,{_pageData:()=>n,default:()=>h});var l=t(641);const n=JSON.parse('{"path":"/notes/%E4%B9%A6%E5%BD%B1%E9%9F%B3%E6%B8%B8/%E6%B8%B8%E6%88%8F/%E5%A1%9E%E5%B0%94%E8%BE%BE%E7%8E%8B%E5%9B%BD%E4%B9%8B%E6%B3%AA.html","title":"塞尔达王国之泪","lang":"zh-CN","frontmatter":{"title":"塞尔达王国之泪","date":"2023-05-24T00:00:00.000Z","tags":["游戏"]},"git":{},"filePathRelative":"notes/书影音游/游戏/塞尔达王国之泪.md"}'),s={name:"塞尔达王国之泪.md"},h=(0,t(6262).A)(s,[["render",function(a,e,t,n,s,h){return(0,l.uX)(),(0,l.CE)("div",null,[...e[0]||(e[0]=[(0,l.Fv)('<h1 id="塞尔达王国之泪" tabindex="-1"><a class="header-anchor" href="#塞尔达王国之泪"><span>塞尔达王国之泪</span></a></h1><p>游戏发售到5月22，玩了有100多个小时（截图这里周六用了复制bug，断网防更新，游玩时长没有同步）</p><p><img src="http://os.zhaohs.cn/markdown/202305231456924.jpg" alt="d70de3c6d7355e6a087189acaa968be"></p><p>只能说真的好玩，每天都玩到半夜两三点。</p><p>周六解锁了所有贤者，只留了最后一个盖侬没打，其余主线都做完了。支线和mini挑战做了少部分，地下树根全开，神庙解锁大半。然后就在网上看到了复制bug、无耐久大师剑bug、烤肉料理bug，都试了一遍之后，周日去打了盖侬，一周目结束。</p><p>因为塞尔达系列只玩过旷野之息，就对比着旷野之息来总结一下（织梦岛和缩小帽都是玩到一半迷宫过不去就不玩了）</p><h2 id="玩法" tabindex="-1"><a class="header-anchor" href="#玩法"><span>玩法</span></a></h2><ol><li>能力 王国之泪里有究极手、余料建造、通天术、倒转乾坤四个大能力，对比旷野之息里的磁铁、时停、造冰和炸弹是要好玩不少的 <ul><li>究极手 王国之泪的核心能力之一，利用地图上的材料和左纳乌装置，可以造载具、战斗工具、高达，整活等等。前期是比较鸡肋的，升几格电池之后可以就造</li></ul></li></ol>',8)])])}]])}}]);